pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // All input slices must have the same length
    assert_eq!(vals_1.len(), vals_2.len(), "vals_1 and vals_2 must have the same length");
    assert_eq!(vals_1.len(), conds_1.len(), "vals_1 and conds_1 must have the same length");
    assert_eq!(vals_1.len(), conds_2.len(), "vals_1 and conds_2 must have the same length");

    let n = vals_1.len();

    // Clear any previous contents and prepare to fill `avgs`
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        // By problem statement, at least one of c1 or c2 is true.
        debug_assert!(c1 || c2, "At least one condition must be true at each index");

        let out = if c1 && c2 {
            // both true: average the two values
            (vals_1[i] + vals_2[i]) / 2
        } else if c1 {
            // only first is true
            vals_1[i]
        } else {
            // only second is true
            vals_2[i]
        };

        avgs.push(out);
    }
}